// v4.12.0: opt-in, local QMD comparison. Never replaces ordinary typing search.
(async()=>{
 if(!['localhost','127.0.0.1','[::1]'].includes(location.hostname))return;
 if(!window.atlasCatalog)await new Promise(resolve=>window.addEventListener('atlas-ready',resolve,{once:true}));
 let status;try{const r=await fetch('/api/search-pilot/status');if(!r.ok)return;status=await r.json();}catch{return;}if(!status.enabled)return;
 const projects=window.atlasCatalog.programs,byId=new Map(projects.map((p,i)=>[p.id,{...p,number:i+1}]));
 const panel=document.createElement('details');panel.className='search-pilot';panel.innerHTML=`<summary>Search comparison pilot · A / B</summary><p>Compare current keyword search (A) with QMD semantic search (B). This is a paired evaluation, not a randomized experiment. Nothing changes on the map until you choose a result set.</p><form><label>Comparison query<input name="query" type="search" maxlength="500" required placeholder="For example: screening without specialist doctors"></label><div class="pilot-filters"><label>Country<select name="country"><option value="">Any country</option></select></label><label>Evidence basis<select name="basis"><option value="">Any evidence basis</option></select></label><label>Publication year<input name="year" type="number" min="1900" max="2100" placeholder="Any year"></label></div><label class="pilot-check"><input type="checkbox" name="deep"> Deep comparison: query expansion and reranking (slower)</label><div class="pilot-actions"><button type="submit">Compare searches</button><button type="button" data-action="copy">Use current search</button><button type="button" data-action="export">Download evaluations</button></div></form><p class="pilot-status" role="status" aria-live="polite">Local pilot · ${projects.length} projects. First use downloads models and builds the index; later queries reuse it.</p><div class="pilot-results"></div><fieldset class="pilot-feedback" hidden><legend>Which result set was more useful?</legend><button type="button" data-vote="A">A · Keywords</button><button type="button" data-vote="B">B · QMD</button><button type="button" data-vote="tie">About equal</button><button type="button" data-vote="neither">Neither</button><label>Evaluation notes<textarea rows="2" maxlength="1000" placeholder="Missed project, irrelevant match, or useful discovery…"></textarea></label><p>Feedback stays in this browser. Download it to compare trials; it is not sent to the Atlas database.</p></fieldset>`;
 document.querySelector('.project-search').append(panel);
 const form=panel.querySelector('form'),message=panel.querySelector('.pilot-status'),results=panel.querySelector('.pilot-results'),feedback=panel.querySelector('.pilot-feedback');let last=null,trial=null,busy=false;
 for(const [name,values]of [['country',[...new Set(projects.flatMap(p=>p.countries||[]))]],['basis',[...new Set(projects.map(p=>p.evidenceBasis).filter(Boolean))]]])for(const value of values.sort())form.elements[name].add(new Option(value,value));
 function evaluations(){try{return JSON.parse(localStorage.getItem('atlas-qmd-evaluations')||'[]');}catch{return [];}}
 function recordVote(vote){if(!last)return;const rows=evaluations().filter(r=>r.trial!==trial);rows.push({...last,trial,at:new Date().toISOString(),vote,notes:feedback.querySelector('textarea').value,catalogSize:projects.length});try{localStorage.setItem('atlas-qmd-evaluations',JSON.stringify(rows.slice(-100)));message.textContent='Evaluation saved in this browser.';}catch{message.textContent='Browser storage is unavailable. Download evaluations before leaving.';}last.vote=vote;last.notes=feedback.querySelector('textarea').value;}
 feedback.addEventListener('click',event=>{const button=event.target.closest('[data-vote]');if(button){recordVote(button.dataset.vote);feedback.querySelectorAll('[data-vote]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));}});
 feedback.querySelector('textarea').addEventListener('change',()=>{if(last?.vote)recordVote(last.vote);});
 panel.querySelector('[data-action=copy]').onclick=()=>{form.elements.query.value=document.querySelector('#project-search').value;};
 panel.querySelector('[data-action=export]').onclick=()=>{const rows=evaluations();if(last&&!rows.some(r=>r.trial===trial))rows.push({...last,trial});const url=URL.createObjectURL(new Blob([JSON.stringify({format:'Hazlitt QMD paired evaluations v1',evaluations:rows},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='Hazlitt-search-evaluations.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
 function column(label,items,ms){const section=document.createElement('section'),heading=document.createElement('h3');heading.textContent=label;section.append(heading);const meta=document.createElement('p');meta.textContent=items.length+' results · '+ms+' ms'+(label.startsWith('B')?' · top 10 semantic candidates':items.length>10?' · showing first 10':'');section.append(meta);const apply=document.createElement('button');apply.type='button';apply.textContent='Show '+label[0]+' on map and results';apply.onclick=()=>window.dispatchEvent(new CustomEvent('atlas-pilot-results',{detail:{query:last.query,ids:items.map(x=>x.id)}}));section.append(apply);const list=document.createElement('ol');for(const item of items.slice(0,10)){const p=byId.get(item.id);if(!p)continue;const row=document.createElement('li'),link=document.createElement('a');link.textContent='Project '+String(p.number).padStart(2,'0')+' · '+p.name;link.href='/?project='+encodeURIComponent(p.id)+'#'+encodeURIComponent(p.id);link.target='_blank';link.rel='noopener';row.append(link);if(item.passage){const text=document.createElement('p');text.textContent=item.passage;row.append(text);}const rating=document.createElement('label');rating.textContent='Relevance ';const select=document.createElement('select');for(const [value,title]of [['','Not rated'],['2','Relevant'],['1','Partly relevant'],['0','Not relevant']])select.add(new Option(title,value));select.onchange=()=>{last.ratings||={};last.ratings[label[0]+':'+item.id]=select.value;if(last.vote)recordVote(last.vote);};rating.append(select);row.append(rating);list.append(row);}if(!items.length){const text=document.createElement('p');text.textContent='No matching projects.';section.append(text);}section.append(list);return section;}
 form.onsubmit=async event=>{event.preventDefault();if(busy)return;busy=true;form.querySelector('[type=submit]').disabled=true;feedback.hidden=true;results.replaceChildren();last=null;message.textContent='Comparing… First use may take several minutes to download and load local models. Ordinary search remains available.';const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),600000);try{const query=form.elements.query.value.trim(),scope=Object.fromEntries(['country','basis','year'].map(k=>[k,form.elements[k].value]));const r=await fetch('/api/search-pilot/compare',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({query,scope,deep:form.elements.deep.checked}),signal:controller.signal});const data=await r.json();if(!r.ok)throw new Error(data.error||'Comparison failed');last=data;trial=crypto.randomUUID();results.append(column('A · Current keywords',data.a,data.aMs),column('B · QMD semantic',data.b,data.bMs));const overlap=data.b.filter(x=>data.a.slice(0,10).some(a=>a.id===x.id)).length;message.textContent=`Comparison for “${data.query}”: ${overlap} shared projects in the first ten. ${data.cached?'Cached trial; displayed search times are from its original run. ':''}Total ${data.totalMs} ms; index preparation ${data.indexMs} ms. B is relevance-ranked; A retains project-number order. Scores are not clinical confidence.`;feedback.hidden=false;feedback.querySelector('textarea').value='';feedback.querySelectorAll('[data-vote]').forEach(b=>b.setAttribute('aria-pressed','false'));}catch(error){message.textContent=error.name==='AbortError'?'Comparison timed out. Keyword search is still available.':error.message+' Keyword search is still available.';}finally{clearTimeout(timer);busy=false;form.querySelector('[type=submit]').disabled=false;}};
})();
